def practice4(figs):
    r=Report(4,'Моделирование бизнес-процесса «как есть»')
    r.h('1 Цель и индивидуальное задание',2)
    r.p('Цель работы — построить модель существующего процесса формирования и актуализации карточек компьютерных систем ООО «Юкомс», определить его входы, выходы, управление, ресурсы и подпроцессы, привязать проблемы обработки информации к конкретным действиям [1].')
    r.p('Индивидуальное задание: использовать описание организации из практики 1 и потоки F01–F14 из практики 2; построить контекстную диаграмму и декомпозицию в IDEF0, описать промежуточные результаты и сделать выводы о состоянии процесса.')
    r.h('2 Этапы выполнения работы',2)
    r.p('Определены границы и результат процесса; составлен перечень ресурсов ICOM; выделены четыре подпроцесса; установлены их связи и возврат на исправление; построены диаграммы A-0 и A0; выполнен анализ недостатков.')
    r.h('3 Характеристика процесса',2)
    r.p('Название процесса — «Сформировать и актуализировать карточку компьютерной системы». Его цель — подготовить корректное товарное предложение и получить подтверждённый результат публикации. Координатор — менеджер маркетплейсов; межфункциональные вопросы и приоритеты разрешает генеральный директор как владелец процесса.')
    r.p('Начало процесса — задание на новую карточку либо изменение состава, цены или доступности компонентов. Окончание — опубликованный вариант с зафиксированным статусом либо документированное решение об отказе или приостановке. Физическая сборка, продажи, доставка и бухгалтерский учёт в модель не включаются.')
    r.page('4 Контекстная модель существующего процесса',True)
    r.p('На рисунке 1 приведена диаграмма A-0: входы I поступают слева, управление C — сверху, механизмы M — снизу, выходы O направлены вправо. Состав ресурсов раскрыт в таблице 1.')
    r.fig(figs['as_context'],'Контекстная диаграмма A-0 процесса «как есть» в IDEF0')
    r.page('5 Входы, выходы и ресурсы процесса',True)
    r.p('Таблица 1 раскрывает стрелки ICOM и их связь с потоками F01–F14 из практики 2.')
    rows=[v[:] for v in ICOM];rows[-1][-1]='Электронные таблицы, папки изображений, почта, сообщения и кабинет продавца'
    r.table('Ресурсы контекстной модели',['Код','Ресурс','Источник или получатель','Краткое описание'],rows,[1.3,5.1,7.1,11.7],compact=True)
    r.page('6 Декомпозиция существующего процесса',True)
    r.p('На рисунке 2 процесс A0 разделён на A1–A4. Горизонтальные и обратные стрелки обозначают передаваемые данные, а не календарную последовательность. D1–D4 — внутренние документы между функциями.')
    r.fig(figs['as_decomp'],'Декомпозиция A0 процесса «как есть» в IDEF0')
    r.page('7 Информационные связи подпроцессов',True)
    r.p('В таблице 2 описаны преобразования информации. Управление распределено следующим образом: A1 — C1; A2 — C1/C2; A3 — C3; A4 — C1/C3. Для каждой функции используются соответствующие участники M1 и средства M2.')
    r.table('Входная, промежуточная и выходная документация',['Код','Подпроцесс','Вход','Промежуточный результат и обработка','Выход','Исполнитель и средства'],AS_SUB,[1.2,4.1,2.5,7.0,6.0,4.4])
    r.p('Баланс модели: I1/I2 поступают в A1; I3 — в A3; I4 — в A4; выходы O1–O3 формирует A4. D1 соединяет A1 с A2, D2 — A2 с A3, D3 — A3 с A4. D4 возвращает замечания к A2; если необходимы новые исходные данные, выполняется новый цикл A1. Входы и выходы нижнего уровня соответствуют контексту.')
    r.page('8 Детализация операций и проблем')
    r.h('8.1 Выполнение функций',2)
    r.p('A1 включает получение задания, сбор предложений, сверку доступности и запрос исходного состава. Если коды компонентов различаются в прайсе и складском учёте, менеджер вручную устанавливает соответствие. До разрешения расхождений данные не считаются полными.')
    r.p('A2 включает выбор компонентов, проверку совместимости, согласование состава и расчёт цены и массы. Производство проверяет технические ограничения, менеджер использует согласованный вариант для ведомости. При возврате изменения проверяются повторно, даже если затронута только часть конфигурации.')
    r.p('A3 включает подготовку названия и описания, перенос характеристик и расчётных значений, запрос изображений и итоговую сверку. Ручное заполнение разных форм создаёт риск несоответствия карточки последней версии BOM.')
    r.p('A4 включает передачу карточки, ожидание внешней обработки, проверку статуса, запись результата и подготовку сводки. При замечаниях карточка возвращается на исправление. При техническом сбое менеджер передаёт данные ИТ-поддержке; успешная передача данных не заменяет проверку итогового статуса.')
    r.h('8.2 Сценарий замены компонента',2)
    r.p('После изменения наличия менеджер выявляет необходимость замены видеокарты. Производство согласует новый компонент, менеджер пересчитывает цену и массу, дизайнер проверяет соответствие изображений. Затем менеджер вручную обновляет связанные карточки. Если одна из них не найдена, в продаже остаётся предложение со старым составом — проявление P-03.')
    r.page('9 Недостатки процесса и выводы')
    r.p('В таблице 3 проблемы сопоставлены с функциями. Оценка влияния качественная: критическое — возможна некорректная конфигурация или цена; высокое — задержки, возвраты и трудности сопровождения.')
    r.table('Привязка недостатков к функциям',['Проблема','Функции','Влияние и направление изменения'],[
    ['P-01 Повторный ввод','A1, A2, A3','Высокое. Централизовать данные и исключить повторный перенос'],
    ['P-02 Совместимость','A2','Критическое. Формализовать и автоматически проверять правила'],
    ['P-03 Замена компонента','A2, A3, A4','Высокое. Находить зависимые BOM и обновлять связанные карточки'],
    ['P-04 Цена и наличие','A1, A2, A4','Критическое. Хранить снимки источников и проверять их актуальность'],
    ['P-05 Неполная карточка','A3, A4','Высокое. Проверять поля до отправки'],
    ['P-06 История операций','A1–A4','Высокое. Связать версии, действия и ответы общим журналом'],
    ],[4.8,2.5,9.2])
    r.p('Построены контекст и декомпозиция модели «как есть», описаны четыре функции и все граничные потоки. Основные недостатки связаны с ручной поддержкой соответствия документов и поздним обнаружением расхождений. В практике 5 эти операции преобразуются в единый управляемый процесс с автоматическими проверками и согласованием ответственных лиц.')
    r.sources(['Албахтин И.В. Информационный менеджмент. Практическая работа 2. Исследование информационных потоков. Москва, 2026.'])
    return r.save()

def practice5(figs):
    r=Report(5,'Моделирование бизнес-процесса «как должно быть»')
    r.h('1 Цель и индивидуальное задание',2)
    r.p('Цель работы — разработать новую технологию формирования и актуализации карточек компьютерных систем ООО «Юкомс», определить изменённые потоки и подпроцессы, построить модель «как должно быть» и оценить ожидаемые результаты преобразования [1].')
    r.p('Индивидуальное задание: преобразовать модель практики 4, сохранив границы процесса и конечного потребителя результата; описать автоматизированные действия, правила принятия решений, ответственность, отчётность и показатели успешности изменения.')
    r.h('2 Этапы выполнения работы',2)
    r.p('Проанализированы причины проблем P-01–P-06; определены новые правила обработки и документы; построены контекст и декомпозиция IDEF0; описано взаимодействие сотрудников и ИС; заданы проверочные сценарии, метрики и порядок внедрения.')
    r.h('3 Новая технология выполнения процесса',2)
    r.p('Данные о компонентах, предложениях, BOM и карточках хранятся в единой системе. Изменение компонента создаёт новую версию BOM и автоматически формирует перечень затронутых карточек. Расчёты и атрибуты формируются из согласованной версии, а не переносятся вручную между файлами.')
    r.p('Система проверяет ограничения и полноту, но решение о допустимости состава принимает производство, а решение о публикации — менеджер. Дизайнер подтверждает соответствие изображений. Отправленный пакет сохраняется вместе с версией, временем, автором и ответом внешней системы. Владелец процесса — генеральный директор, координатор — менеджер маркетплейсов.')
    r.page('4 Изменения и устранение причин проблем',True)
    r.p('Таблица 1 показывает существенные отличия новой технологии. Для каждой проблемы указано изменение соответствующей функции и ожидаемый результат.')
    r.table('Сопоставление технологий выполнения процесса',['Код','Как есть','Как должно быть','Ответственный и эффект'],[
    ['P-01','Раздельные таблицы и повторное заполнение','Единые справочники; генерация расчётов и полей из версии BOM','Менеджер; сокращение повторного ввода'],
    ['P-02','Проверка совместимости по отдельным сведениям','Проверка по справочнику правил до согласования BOM','Производство; предотвращение критических ошибок'],
    ['P-03','Поиск затронутых карточек вручную','Расчёт зависимостей, новая версия, согласование изменений','Производство и менеджер; полнота актуализации'],
    ['P-04','Сверка цен и наличия в разное время','Снимки с датами, проверка возраста данных перед отправкой','Менеджер; контроль актуальности предложения'],
    ['P-05','Ошибки обнаруживаются при внешней обработке','Проверка обязательных атрибутов и изображений до публикации','Менеджер и дизайнер; меньше возвратов'],
    ['P-06','История в переписке и отдельных файлах','Единый журнал версии, согласования, попытки и ответа','ИТ и менеджер; воспроизводимость и разбор сбоев'],
    ],[1.8,6.2,9.5,7.7])
    r.page('5 Контекст новой технологии',True)
    r.p('На рисунке 1 приведена целевая модель A-0. Входы и бизнес-управление сохранены; механизм M2 заменён проектируемой ИС. Дополнительный выход O4 объединяет документы автоматического контроля и прослеживаемости.')
    r.fig(figs['to_context'],'Контекстная диаграмма A-0 процесса «как должно быть»')
    r.page('6 Потоки и ресурсы новой технологии',True)
    r.p('В таблице 2 раскрыты стрелки ICOM. Новые документы N01–N05 входят в выход O4.')
    rows=[v[:] for v in ICOM]
    rows[0][-1]='Заявка с основанием и ссылкой на текущую версию BOM'
    rows[1][-1]='Предложения и остатки с датами источника и загрузки'
    rows[2][-1]='Файлы изображений, связанные с версией BOM'
    rows[3][-1]='Статус обработки либо замечания к отправленному пакету'
    rows[4][-1]='Утверждённый пакет определённой версии карточки'
    rows[5][-1]='Статус попытки, адресные замечания и ответственная роль для исправления'
    rows[6][-1]='Очередь работ, актуальность данных, сроки, ошибки и показатели пилота'
    rows.insert(7,['O4','Контрольные документы','Менеджер, производство, дизайнер, ИТ','N01–N05: проверки, зависимости, расчёт, изображения и история'])
    rows[-1][-1]='Проектируемая ИС, единая БД, хранилище файлов, очередь публикаций и адаптеры обмена'
    r.table('ICOM новой технологии',['Код','Ресурс','Источник или получатель','Краткое описание'],rows,[1.3,5.1,7.1,11.7],compact=True)
    r.page('7 Декомпозиция новой технологии',True)
    r.p('На рисунке 2 сохранены четыре функциональные области A1–A4 для сопоставления с практикой 4. Изменены внутренние процедуры, состав документов и распределение работы между сотрудниками и системой.')
    r.fig(figs['to_decomp'],'Декомпозиция A0 процесса «как должно быть»')
    r.page('8 Взаимодействие целевых подпроцессов',True)
    r.p('Таблица 3 раскрывает преобразования данных и передачу ответственности. Управление: A1 — C1; A2 — C1/C2; A3 — C3; A4 — C1/C3. Средства M2 и участники M1 обеспечивают каждую функцию в пределах её полномочий.')
    r.table('Документы и ответственность целевых подпроцессов',['Код','Подпроцесс','Вход','Обработка и промежуточные данные','Выход','Ответственность'],TO_SUB,[1.2,4.1,2.5,7.0,6.0,4.4])
    r.p('Баланс сохраняется: I1/I2 входят в A1, I3 — в A3, I4 — в A4. D1–D3 последовательно передают версии и результаты; A4 выдаёт O1–O4. Контрольные документы, созданные в A2/A3, проходят в составе D2/D3 и включаются A4 в итоговый комплект O4. D4 возвращает замечания к проверке данных; при изменении источников запускается A1.')
    r.page('9 Новые документы и бизнес-правила')
